function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  riskUrl: 'https://httpbin.org/post',
  approvalUrl: 'https://httpbin.org/post',
  timeoutMs: 20000,
  renewalWindowDays: 90,
  policies: {
    autoApproveBelow: 10000,
    managerBelow: 50000,
    directorBelow: 250000
  },
  allowSimulation: true
};

const hook = ref('Webhook - Contract Intake');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const contractId = String(body.contractId || body.id || ('CTR-' + Date.now())).trim();
const title = String(body.title || body.name || '').trim();
const vendor = String(body.vendor || body.counterparty || '').trim();
const value = Number(body.value || body.amount || 0);
const startDate = String(body.startDate || body.start_date || '').trim();
const endDate = String(body.endDate || body.end_date || body.expiryDate || '').trim();
const type = String(body.type || body.contractType || 'general').toLowerCase();
const owner = String(body.owner || body.ownerEmail || '').trim();
const department = String(body.department || 'general').toLowerCase();

if (!title) errors.push('title is required');
if (!vendor) errors.push('vendor / counterparty is required');
if (!endDate) errors.push('endDate / expiryDate is required');
if (!Number.isFinite(value) || value < 0) errors.push('value must be a non-negative number');

const valid = errors.length === 0;

let riskUrl = CONFIG.riskUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  riskUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    contract: {
      contractId,
      title,
      vendor,
      value,
      startDate: startDate || null,
      endDate,
      type,
      owner: owner || null,
      department
    },
    urls: {
      risk: riskUrl,
      approval: CONFIG.approvalUrl
    },
    requestId: body.requestId || ('clm-' + Date.now())
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Validate & Normalize');
const c = ctx.contract;
const windowDays = ctx.config.renewalWindowDays;

let daysToExpiry = null;
let renewalStatus = 'unknown';
let needsRenewalAction = false;

try {
  const end = new Date(c.endDate);
  const now = new Date();
  daysToExpiry = Math.ceil((end - now) / (1000 * 60 * 60 * 24));

  if (daysToExpiry < 0) {
    renewalStatus = 'expired';
    needsRenewalAction = true;
  } else if (daysToExpiry <= 30) {
    renewalStatus = 'critical';
    needsRenewalAction = true;
  } else if (daysToExpiry <= windowDays) {
    renewalStatus = 'upcoming';
    needsRenewalAction = true;
  } else {
    renewalStatus = 'active';
    needsRenewalAction = false;
  }
} catch (e) {
  renewalStatus = 'invalid_date';
}

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    contract: c,
    urls: ctx.urls,
    renewal: {
      daysToExpiry,
      status: renewalStatus,
      needsAction: needsRenewalAction,
      windowDays
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Renewal Detection');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }

// Prefer API score; fallback to heuristic
let score = Number(body.score || body.riskScore);
if (!Number.isFinite(score)) {
  score = 20;
  if (ctx.contract.value >= 100000) score += 30;
  else if (ctx.contract.value >= 25000) score += 15;
  if (ctx.renewal.status === 'expired' || ctx.renewal.status === 'critical') score += 25;
  if (['msa', 'dpa', 'security'].includes(ctx.contract.type)) score += 15;
  score = Math.min(score, 100);
}

let tier = 'low';
if (score >= 70) tier = 'high';
else if (score >= 40) tier = 'medium';

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    contract: ctx.contract,
    urls: ctx.urls,
    renewal: ctx.renewal,
    risk: {
      score,
      tier,
      apiStatus: status,
      apiOk: status >= 200 && status < 300
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process Risk Score');
const p = ctx.config.policies;
const value = ctx.contract.value;
const riskTier = ctx.risk.tier;
const needsRenewal = ctx.renewal.needsAction;

let requiredLevels = [];
let autoApproved = false;

if (value < p.autoApproveBelow && riskTier === 'low' && !needsRenewal) {
  autoApproved = true;
} else {
  requiredLevels.push('manager');
  if (value >= p.managerBelow || riskTier === 'medium' || riskTier === 'high') {
    requiredLevels.push('director');
  }
  if (value >= p.directorBelow || riskTier === 'high') {
    requiredLevels.push('executive');
  }
}

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    contract: ctx.contract,
    urls: ctx.urls,
    renewal: ctx.renewal,
    risk: ctx.risk,
    policy: {
      autoApproved,
      requiredLevels,
      maxLevel: requiredLevels.length ? requiredLevels[requiredLevels.length - 1] : null
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Evaluate Approval Policy');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

const auto = ctx.policy.autoApproved;
const approved = auto || (status >= 200 && status < 300);

let lifecycleStatus = 'approved';
if (!approved) lifecycleStatus = 'rejected';
else if (ctx.renewal.needsAction) lifecycleStatus = 'approved_pending_renewal';
else lifecycleStatus = 'approved_active';

return [{
  json: {
    requestId: ctx.requestId,
    contract: ctx.contract,
    renewal: ctx.renewal,
    risk: ctx.risk,
    policy: ctx.policy,
    approval: {
      autoApproved: auto,
      approved,
      apiStatus: status,
      decidedAt: new Date().toISOString()
    },
    lifecycleStatus
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process Approval Result');

const report = {
  requestId: ctx.requestId,
  contractId: ctx.contract.contractId,
  title: ctx.contract.title,
  vendor: ctx.contract.vendor,
  value: ctx.contract.value,
  renewal: ctx.renewal,
  risk: {
    score: ctx.risk.score,
    tier: ctx.risk.tier
  },
  policy: {
    autoApproved: ctx.policy.autoApproved,
    requiredLevels: ctx.policy.requiredLevels
  },
  approval: ctx.approval,
  lifecycleStatus: ctx.lifecycleStatus,
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    requestId: ctx.requestId,
    report,
    lifecycleStatus: ctx.lifecycleStatus
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Build Lifecycle Report');

const httpStatus = ctx.lifecycleStatus === 'rejected' ? 403 : 200;

const body = {
  status: ctx.lifecycleStatus,
  requestId: ctx.requestId,
  report: ctx.report
};

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.requestId
  }
}];
